                : `data:image/jpeg;base64,${input}`;

              const body = {
                model: useModel,
                stream: true,
                messages: [{ role: 'user', content: [
                  { type: 'text', text: sysMessage },
                  { type: 'image_url', image_url: { url: dataUrl } },
