    crisisResponse: "I am detecting signals of severe distress. I care about your safety. Please, I urge you to call emergency services or a suicide prevention hotline immediately.",
    silenceThreshold: 800,
    openaiEndpoint: 'http://127.0.0.1:11434',
};

const STATE = {
    idle: 0,
    listening: 1,
    thinking: 2,
    speaking: 3,
    crisis: 4
};

function App() {
    const [currentMode, setCurrentMode] = useState(STATE.idle);
    const [memory, setMemory] = useState([]);
    const [currentTranscript, setCurrentTranscript] = useState("");
    const silenceTimerRef = useRef(null);

    useEffect(() => {
        warmUpBrain();
        setupAudio();

        // Cleanup function to stop recognition
        return () => {
            if (recognition) recognition.stop();
        };
    }, []);

    let audioContext;
    let synth = window.speechSynthesis;
    let recognition;

    const warmUpBrain = async () => {
        try {
            console.log("Neural Net Warmup Initiated");
        } catch(e) {}
    };

    const setupAudio = () => {
        const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        if (!Recognition) return alert("Browser not supported. Please use Chrome.");

        recognition = new Recognition();
        recognition.continuous = true; 
        recognition.lang = 'en-US'; 
        recognition.interimResults = true; 

        recognition.onstart = () => {
            if(currentMode !== STATE.speaking) {
                setCurrentMode(STATE.listening);
                updateStatus("LISTENING...");
            }
        };

        recognition.onresult = async (event) => {
            clearTimeout(silenceTimerRef.current);
            const results = event.results;
            const lastResult = results[results.length - 1];
            setCurrentTranscript(lastResult[0].transcript);

            document.getElementById('transcript').innerText = `"${currentTranscript}"`;

            silenceTimerRef.current = setTimeout(async () => {
                recognition.stop();
                processUserSpeech(currentTranscript);
            }, CONFIG.silenceThreshold);
        };

        recognition.onend = () => {
            if (currentMode === STATE.listening) {
                recognition.start();
            }
        };
    };

    const processUserSpeech = async (text) => {
        if (!text || text.trim().length < 1) {
            setCurrentMode(STATE.listening);
            try { recognition.start(); } catch(e){}
            return;
        }

        setCurrentMode(STATE.thinking);
        updateStatus("ANALYZING...");

        const answer = await queryBrain(text);
        speak(answer);
    };

    const speak = (text) => {
        synth.cancel();
        setCurrentMode(STATE.speaking);
        updateStatus("RESPONDING...");

        const utter = new SpeechSynthesisUtterance(text);

        const voices = synth.getVoices();
        let voice = voices.find(v => v.name.includes("Google UK English Female"));
        if (!voice) voice = voices.find(v => v.lang === "en-GB" && v.name.includes("Female"));
        if (!voice) voice = voices.find(v => v.lang === "en-GB");

        if (voice) utter.voice = voice;
        utter.pitch = 1.0; 
        utter.rate = 0.9; 

        utter.onend = () => {
            setCurrentMode(STATE.listening);
            recognition.start();
        };

        synth.speak(utter);
    };

    const queryBrain = async (text) => {
        // Simulate fetching a response from the brain
        return `You said: ${text}`;
    };

    const updateStatus = (statusText) => {
        document.getElementById('status-display').innerText = statusText;
        if (currentMode === STATE.crisis) {
            document.getElementById('status-display').style.color = 'red';
        } else {
            document.getElementById('status-display').style.color = 'var(--iris-primary)';
        }
    };

    const bootStrapApp = () => {
        warmUpBrain();
        setupAudio();
        synth.onvoiceschanged = () => {
            speak("Hello, I am your assistant. How can I help you today?");
        };
    };

    useEffect(() => {
        bootStrapApp();
    }, []);

    return (
        <div className="App">
            <BioEyeCanvas />
            <StatusDisplay currentMode={currentMode} />
            <TranscriptDisplay currentTranscript={currentTranscript} />
            <div id="start-screen" onClick={() => bootStrapApp()}>
                <h1>Start</h1>
                <p>Click to begin</p>
            </div>
        </div>
    );
}

export default App;
