          expandQuery: (query: string, signal?: AbortSignal) =>
            _expandQuery(query, resolvedOllamaEndpoints, resolvedModel, signal),
          /**
           * Run a solutions debate: prompt → keywords → 2 personas → LLM debate → solutions manifest.
