           */
          beaming: (prompt: string, opts: { taskType?: 'chat' | 'thinking' | 'json' | 'vision'; signal?: AbortSignal; concurrency?: number } = {}) =>
            _beaming(prompt, resolvedOllamaEndpoints, resolvedModel, opts),

          UploadFile: async () => {},
