    /**
     * Retrieve the full messages array of a ChatSession by its ID.
     *
     * Usage:
     *   const messages = await client.getMessages('session-id-123');
     */
    async getMessages(sessionId: string): Promise<any[]> {
      if (!sessionId) return [];
